import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

public class Main {
    record Block(String name, int size, boolean live) {}

    // 标记-清除：dead block 变成 free block，live block 位置不变，留下碎片
    static List<Block> markSweep(List<Block> heap) {
        List<Block> result = new ArrayList<>();
        for (Block block : heap) {
            result.add(block.live() ? block : new Block("free", block.size(), false));
        }
        return result;
    }

    // 复制/迁移：只搬 live block 到连续区域，原空间可整体清空
    static List<Block> copyLive(List<Block> heap) {
        return heap.stream()
                .filter(Block::live)
                .map(block -> new Block(block.name(), block.size(), true))
                .collect(Collectors.toList());
    }

    // 标记-整理：live block 连续排列，剩余空间合并成一个大 free block
    static List<Block> compact(List<Block> heap) {
        List<Block> result = copyLive(heap);
        int freeBytes = heap.stream()
                .filter(block -> !block.live())
                .mapToInt(Block::size).sum();
        if (freeBytes > 0) result.add(new Block("free", freeBytes, false));
        return result;
    }

    static int liveBytes(List<Block> heap) {
        return heap.stream().filter(Block::live).mapToInt(Block::size).sum();
    }

    static int largestFreeBlock(List<Block> heap) {
        return heap.stream()
                .filter(block -> !block.live())
                .mapToInt(Block::size)
                .max().orElse(0);
    }

    static int freeFragmentCount(List<Block> heap) {
        return (int) heap.stream().filter(block -> !block.live()).count();
    }

    static String layout(List<Block> heap) {
        return heap.stream()
                .map(block -> "[" + block.name() + ":" + block.size() + "]")
                .collect(Collectors.joining(""));
    }

    public static void main(String[] args) {
        // 模拟堆：A(3) dead(2) B(4) dead(1) C(2)，存活率 = 9/12 = 75%
        List<Block> heap = List.of(
                new Block("A", 3, true),
                new Block("dead", 2, false),
                new Block("B", 4, true),
                new Block("dead", 1, false),
                new Block("C", 2, true)
        );

        List<Block> swept = markSweep(heap);
        List<Block> copied = copyLive(heap);
        List<Block> compacted = compact(heap);

        System.out.println("before  : " + layout(heap));
        System.out.println("sweep   : " + layout(swept)
                + " | largestFree=" + largestFreeBlock(swept)
                + " fragments=" + freeFragmentCount(swept));
        System.out.println("copy    : " + layout(copied)
                + " | copiedBytes=" + liveBytes(copied)
                + " (needs to-space)");
        System.out.println("compact : " + layout(compacted)
                + " | largestFree=" + largestFreeBlock(compacted));

        // 标记-清除：两个碎片块 (2, 1)，最大连续空闲只有 2
        assert freeFragmentCount(swept) == 2 : "sweep should leave 2 free fragments";
        assert largestFreeBlock(swept) == 2;
        // 复制：需要搬 9 字节 live 数据到 to-space
        assert liveBytes(copied) == 9;
        assert layout(copied).equals("[A:3][B:4][C:2]");
        // 整理：所有 free 合并为 3 字节连续块
        assert largestFreeBlock(compacted) == 3;
        assert freeFragmentCount(compacted) == 1;

        System.out.println();
        System.out.println("tradeoff summary:");
        System.out.println("  sweep: 不搬对象，但留下 " + freeFragmentCount(swept) + " 个碎片块");
        System.out.println("  copy:  搬 " + liveBytes(copied) + " 字节，需要等量 to-space，低存活率时划算");
        System.out.println("  compact: 搬对象 + 更新引用，但得到 " + largestFreeBlock(compacted) + " 字节连续空间");
    }
}
